import { createHmac } from 'node:crypto';

export const SHA1_DIGEST_LENGTH = 20;

export function hmacSha1(key, ...chunks) {
  const hmac = createHmac('sha1', key);

  for (const chunk of chunks) {
    hmac.update(chunk);
  }

  return hmac.digest();
}

