import {
  buildError,
  buildHelp,
  formatPythonLikeString,
  getProgramName,
} from './messages.mjs';

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;
const INTEGER_PATTERN = /^[+-]?(?:\d(?:_?\d)*)$/;
const OPTION_KEYS = ['a', 'b', 'c'];

export class CliMessageError extends Error {
  constructor(status, streamName, text) {
    super(text);
    this.name = 'CliMessageError';
    this.status = status;
    this.streamName = streamName;
    this.text = text;
  }
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];
  let stopOptionParsing = false;
  let helpRequested = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (stopOptionParsing) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      stopOptionParsing = true;
      continue;
    }

    const parsedOption = parseOptionToken(token);

    if (parsedOption.kind === 'help_with_argument') {
      throw cliParseError(
        programName,
        `argument -h/--help: ignored explicit argument ${formatPythonLikeString(parsedOption.argument)}`,
      );
    }

    if (parsedOption.kind === 'help') {
      helpRequested = true;
      continue;
    }

    if (parsedOption.kind === 'named_option') {
      const rawValue =
        parsedOption.inlineValue !== null
          ? parsedOption.inlineValue
          : takeOptionValue(argv, index, parsedOption.token, programName);

      if (parsedOption.inlineValue === null) {
        index += 1;
      }

      if (parsedOption.name === 'c') {
        values.c = parseIntegerArgument(rawValue, programName);
      } else {
        values[parsedOption.name] = rawValue;
      }

      continue;
    }

    extras.push(token);
  }

  if (helpRequested) {
    throw new CliMessageError(0, 'stdout', buildHelp(programName));
  }

  const missingOptions = OPTION_KEYS.filter((key) => values[key] === undefined).map(
    (key) => `--${key}`,
  );

  if (missingOptions.length > 0) {
    throw cliParseError(
      programName,
      `the following arguments are required: ${missingOptions.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    throw cliParseError(
      programName,
      `unrecognized arguments: ${extras.join(' ')}`,
    );
  }

  return values;
}

function cliParseError(programName, message) {
  return new CliMessageError(2, 'stderr', buildError(programName, message));
}

function parseOptionToken(token) {
  if (token === '-h') {
    return { kind: 'help' };
  }

  if (token.startsWith('-h=')) {
    return {
      kind: 'help_with_argument',
      argument: token.slice(3),
    };
  }

  if (token.startsWith('-h')) {
    return { kind: 'help' };
  }

  if (!token.startsWith('--') || token === '--') {
    return { kind: 'other' };
  }

  const equalsIndex = token.indexOf('=');
  const optionText = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const inlineValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);

  if (optionText === '--a' || optionText === '--b' || optionText === '--c') {
    return {
      kind: 'named_option',
      name: optionText.slice(2),
      token: optionText,
      inlineValue,
    };
  }

  if ('--help'.startsWith(optionText) && optionText.length >= 3) {
    if (inlineValue !== null) {
      return {
        kind: 'help_with_argument',
        argument: inlineValue,
      };
    }

    return { kind: 'help' };
  }

  return { kind: 'other' };
}

function takeOptionValue(argv, optionIndex, optionToken, programName) {
  const valueIndex = optionIndex + 1;

  if (valueIndex >= argv.length) {
    throw cliParseError(programName, `argument ${optionToken}: expected one argument`);
  }

  const candidate = argv[valueIndex];

  if (looksLikeOption(candidate) && !NEGATIVE_NUMBER_PATTERN.test(candidate)) {
    throw cliParseError(programName, `argument ${optionToken}: expected one argument`);
  }

  return candidate;
}

function looksLikeOption(token) {
  return token.length > 1 && token.startsWith('-');
}

function parseIntegerArgument(rawValue, programName) {
  const trimmedValue = rawValue.trim();

  if (!INTEGER_PATTERN.test(trimmedValue)) {
    throw cliParseError(
      programName,
      `argument --c: invalid int value: ${formatPythonLikeString(rawValue)}`,
    );
  }

  return Number(trimmedValue.replace(/_/g, ''));
}

