import { SHA1_DIGEST_LENGTH, hmacSha1 } from './hmac_sha1.mjs';

export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export function derivePbkdf2Sha1(password, salt, iterations, derivedKeyLength) {
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new ValueError('iterations must be at least 1');
  }

  if (!Number.isInteger(derivedKeyLength) || derivedKeyLength < 1) {
    throw new ValueError('derived key length must be at least 1');
  }

  const passwordBytes = Buffer.from(password, 'utf8');
  const saltBytes = Buffer.from(salt, 'utf8');
  const blockCount = Math.ceil(derivedKeyLength / SHA1_DIGEST_LENGTH);
  const derived = Buffer.alloc(blockCount * SHA1_DIGEST_LENGTH);

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    const block = deriveBlock(passwordBytes, saltBytes, iterations, blockIndex);
    block.copy(derived, (blockIndex - 1) * SHA1_DIGEST_LENGTH);
  }

  return derived.subarray(0, derivedKeyLength);
}

export function derivePbkdf2Sha1Hex(password, salt, iterations, derivedKeyLength) {
  return derivePbkdf2Sha1(password, salt, iterations, derivedKeyLength).toString('hex');
}

function deriveBlock(passwordBytes, saltBytes, iterations, blockIndex) {
  const blockIndexBytes = Buffer.allocUnsafe(4);
  blockIndexBytes.writeUInt32BE(blockIndex, 0);

  let intermediate = hmacSha1(passwordBytes, saltBytes, blockIndexBytes);
  const accumulator = Buffer.from(intermediate);

  for (let round = 1; round < iterations; round += 1) {
    intermediate = hmacSha1(passwordBytes, intermediate);
    xorInto(accumulator, intermediate);
  }

  return accumulator;
}

function xorInto(target, source) {
  for (let index = 0; index < target.length; index += 1) {
    target[index] ^= source[index];
  }
}

